import{_ as e}from"./chunks/hub.pc.en.Cb61JjFk.js";import{_ as o}from"./chunks/hub-robots.pc.en.Du0Wyhqd.js";import{_ as a}from"./chunks/home-status.pc.en.KhsLj-pc.js";import{_ as n,o as r,c as i,a5 as s}from"./chunks/framework.D47SInms.js";const c="/RBQ/nightly/images/app/boot-prestart.pc.en.png",l="/RBQ/nightly/images/app/boot-autostart-confirm.pc.en.png",d="/RBQ/nightly/images/app/boot-autostart-running.pc.en.png",v=JSON.parse('{"title":"Controller and Wi-Fi","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/operation/controller-wifi-connect.md","filePath":"manual/operation/controller-wifi-connect.md","lastUpdated":1791600043000}'),h={name:"manual/operation/controller-wifi-connect.md"};function p(u,t,g,m,b,f){return r(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="controller-and-wi-fi" tabindex="-1">Controller and Wi-Fi <a class="header-anchor" href="#controller-and-wi-fi" aria-label="Permalink to &quot;Controller and Wi-Fi&quot;">​</a></h1><p>How to put the controller (Steam Deck, tablet, or PC) on the robot&#39;s Wi-Fi, connect the RBQ app to the robot, and run the auto-start. Set the initial pose and power the robot on first — see <a href="./initial-pose.html">Robot initial pose</a>.</p><h2 id="step-1-open-the-app" tabindex="-1">Step 1: Open the app <a class="header-anchor" href="#step-1-open-the-app" aria-label="Permalink to &quot;Step 1: Open the app&quot;">​</a></h2><p>Launch the <strong>RBQ</strong> app on the controller. If it is not yet installed on a Steam Deck, start with <a href="/RBQ/nightly/manual/troubleshooting/steamdeck-setup.html">Steam Deck setup</a>. The installers are on <a href="/RBQ/nightly/manual/downloads/">Downloads</a>.</p><h2 id="wifi" tabindex="-1">Step 2: Join the robot&#39;s Wi-Fi <a class="header-anchor" href="#wifi" aria-label="Permalink to &quot;Step 2: Join the robot&#39;s Wi-Fi {#wifi}&quot;">​</a></h2><p>The robot provides a Wi-Fi access point named <code>RBQ_{XX}</code> (XX differs per unit). The controller must be on that network to reach the robot.</p><p>The app opens on the <strong>hub</strong>. The robot name sits at the top left with the connection state right after it, and that status line is what tells you whether the device is on the right network.</p><p><img src="'+e+'" alt="The hub — robot name and status line"></p><ol><li><strong>Read the status line</strong> — <code>Connect to the robot&#39;s WiFi</code> means no robot is saved yet, and <code>Not on the robot&#39;s WiFi</code> means the device is on some other network. When the app knows the robot&#39;s WiFi it names it (<em>Robot WiFi(SSID) — please switch to it</em>).</li><li><strong>Switch networks</strong> — on Linux desktop and Steam Deck the <code>Switch WiFi</code> button next to the line joins that network directly, or opens the in-app list so you can pick <code>RBQ_{XX}</code>; enter the password there if the network is secured. On Android, <code>WiFi settings</code> opens the system Wi-Fi screen instead.</li><li><strong>Confirm</strong> — you are ready once the dot in front of the robot name turns green.</li></ol><p>If <code>RBQ_{XX}</code> is not in the list, check that the robot is powered on and its Wi-Fi is up.</p><p>Once you reach the control home, the Wi-Fi chip in its top bar shows the signal strength. Tap it for <strong>My device WiFi</strong>, which names the network your device is on and shows a <code>Robot network</code> (green) or <code>Not robot network</code> (amber) badge.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>Android policy forbids scanning from inside the app, so it offers only a <strong>System WiFi settings</strong> button. iOS and browser builds cannot read or change Wi-Fi either — join the network from the device&#39;s own Wi-Fi settings.</p></div></div><h2 id="connect" tabindex="-1">Step 3: Connect to the robot <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;Step 3: Connect to the robot {#connect}&quot;">​</a></h2><p>Robots are chosen and added on the hub. There is no connection screen inside Settings.</p><ol><li><strong>Tap the robot name (▾)</strong> to open <strong>Select robot</strong>. It lists the robots saved on this device and, while you are logged in, the robots assigned to your account.</li><li><strong>Tap the robot&#39;s row</strong> to connect. On Linux desktop and Steam Deck the app switches to the robot&#39;s WiFi first when that network is saved and in range.</li><li><strong>For a robot you have not used before</strong>, press <code>Add robot</code>. On the robot&#39;s own AP the app finds it by itself at the fixed address <code>192.168.0.10</code> — <code>Check again</code> retries. A robot behind a router or reachable at a public address is added under <strong>Connect by address</strong> (<code>Robot IP</code>, preset to <code>192.168.0.10</code>, or <code>Public IP</code>), and <code>Enter access code</code> registers the robots assigned to your account for remote (LTE) use.</li><li><strong>Communication is open</strong> once the dot is green and the line reads <code>Connected</code> followed by the route.</li></ol><p><img src="'+o+'" alt="Select robot"></p><p>The routes, the automatic connection at start-up and what each status line means are covered in <a href="/RBQ/nightly/manual/gui/connection.html">Connection</a>.</p><h2 id="auto-start" tabindex="-1">Step 4: Auto-start <a class="header-anchor" href="#auto-start" aria-label="Permalink to &quot;Step 4: Auto-start {#auto-start}&quot;">​</a></h2><p>This brings the robot software and state up in one go.</p><ol><li><strong>Press auto-start</strong> — before start-up, an <code>Auto Start</code> button sits on the hub under the robot status, and at the bottom center of the control home. (The hub card only appears once a robot is connected; the control-home pill is there before that, but grayed out.)</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+c+'" alt="Auto start button on the pre-start home screen" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Home screen before start-up ]</figcaption></figure><ol start="2"><li><strong>Confirm</strong> — a confirmation appears. Check that the robot is on flat ground with every foot and knee touching it, then press <code>Auto Start</code>. The row in the middle lists the stages ahead: <code>POWER</code>, <code>CAN-BUS</code>, <code>HOMING</code>, <code>IMU-CHECK</code>, <code>START</code>.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+l+'" alt="Auto-start confirmation" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Auto-start confirmation ]</figcaption></figure><ol start="3"><li><strong>Watch it run</strong> — the same window turns into the <strong>start-up sequence</strong> and reports each stage as it completes, per leg and per joint with its elapsed time, so a failure points straight at the joint responsible.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+d+'" alt="Auto-start in progress" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Auto-start in progress ]</figcaption></figure><ol start="4"><li><strong>Confirm completion</strong> — start-up is done once every item reads as complete and the robot is standing. Press the status in the top bar to review the individual results.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+a+'" alt="Status popover after start-up" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Start-up complete — status ]</figcaption></figure><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>If auto-start does not finish, or an item is left failed, make sure nobody is nearby, review the <a href="/RBQ/nightly/manual/safety/emergency-stop-procedures">emergency stop procedures</a>, and follow the steps below. Always observe the <a href="/RBQ/nightly/manual/safety/general-safety-warning-precautions">general safety precautions</a> before operating.</p><ol style="margin:0.5rem 0 0 1.25rem;"><li>If the communication check failed: power the robot down safely and restart it.</li><li>If finding the home pose failed: check the leg posture on a flat, stable surface as described in <a href="/RBQ/nightly/manual/safety/maintenance-safety">maintenance safety</a>, then restart.</li></ol><p style="margin-top:0.75rem;">If the problem persists, contact Rainbow Robotics as described on the <a href="/RBQ/nightly/manual/support/">Contact</a> page.</p></div></div>',28)])])}const _=n(h,[["render",p]]);export{v as __pageData,_ as default};
